def restore_victory_road_text(path, source):
    if str(path) != "src/data/wild_encounters.json":
        return source
    for label, original in ORIGINAL_VICTORY_ROAD.items():
        marker = '"base_label": "' + label + '"'
        start = source.index(marker)
        i = source.index('"mons": [', start)
        current = BALANCED_VICTORY_ROAD[label]
        assert source[i:i+len(current)] == current, label
        source = source[:i] + original + source[i+len(current):]
    return source

def prior_victory_road_source(path):
    return restore_victory_road_text(path, prior_route23_source(path).decode("utf-8")).encode("utf-8")

def restore_prior_victory_road_text(path, source):
    return restore_victory_road_text(path, restore_prior_route23_text(path, source))
